INSERT INTO talent_evidence (talent_id, position, kind, prompt, excerpt, skills) SELECT talent_id, position, kind, prompt, excerpt, skills FROM jsonb_to_recordset('[{"talent_id":"T-01","position":0,"kind":"scenario","prompt":"A patient refuses their evening medication. What do you do?","excerpt":"Sit down, ask what worries them, check if it''s side effects or confusion, then document and inform the doctor rather than pushing.","skills":["patient-care","medication"]},{"talent_id":"T-01","position":1,"kind":"voice","prompt":"60-second voice note: working with people from many backgrounds","excerpt":"On my ward we had patients speaking five languages. I learned to use pictures and family members carefully, and to check understanding twice.","skills":["intercultural"]},{"talent_id":"T-02","position":0,"kind":"scenario","prompt":"You arrive and a client is confused and hasn''t eaten. First steps?","excerpt":"Check blood sugar and fluids, look for signs of infection, call the nurse on duty, and leave a clear note for the next visit.","skills":["elderly-care","patient-care"]},{"talent_id":"T-03","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"Rebuilt a date picker so it''s fully keyboard-navigable; documented ARIA decisions in the PR.","skills":["react","a11y"]},{"talent_id":"T-03","position":1,"kind":"scenario","prompt":"A designer hands you a low-contrast mockup. What do you do?","excerpt":"Show them the contrast ratio next to WCAG AA, suggest two token tweaks, and ship with their sign-off.","skills":["ux","a11y"]},{"talent_id":"T-04","position":0,"kind":"voice","prompt":"60-second voice note: a shift that went wrong","excerpt":"Two pickers called in sick before a big order. I re-split zones by SKU weight, took a scanner myself, and we shipped 20 minutes late instead of two hours.","skills":["warehouse","lead"]},{"talent_id":"T-05","position":0,"kind":"scenario","prompt":"A truck is stuck at the border and the customer is calling. What do you do?","excerpt":"Get a realistic ETA from the driver first, then call the customer with two options: partial delivery from local stock or a new slot tomorrow.","skills":["logistics","stakeholders"]},{"talent_id":"T-06","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"A small Django API for a food bank''s pickup schedule, with tests for double bookings.","skills":["backend","python","testing"]},{"talent_id":"T-06","position":1,"kind":"voice","prompt":"60-second voice note: what your old job taught you","excerpt":"A kitchen at 8 pm is a production incident every night. You learn to call things out early and never leave your station messy.","skills":["team"]},{"talent_id":"T-07","position":0,"kind":"scenario","prompt":"A sensor feed suddenly doubles in volume. What do you do first?","excerpt":"Check whether it''s real load or duplicated messages: I''d sample timestamps per device, then add idempotent keys at ingest so reprocessing is safe.","skills":["pipelines","problem"]},{"talent_id":"T-07","position":1,"kind":"sample","prompt":"Small work sample","excerpt":"Wrote a 40-line Python parser for CAN-bus logs with tests for malformed frames.","skills":["python","embedded"]},{"talent_id":"T-08","position":0,"kind":"scenario","prompt":"Developers want to reuse patient notes to train a triage model. What do you ask first?","excerpt":"What''s the legal basis and is it secondary use under Findata rules? Then: can we do it with structured fields only, pseudonymised, before touching free text?","skills":["health-regs","ehr"]},{"talent_id":"T-09","position":0,"kind":"voice","prompt":"60-second voice note: explain something technical simply","excerpt":"I explained median vs mean to parents using bus delays — one very late bus shouldn''t change how you plan your morning.","skills":["stakeholders","mentoring"]},{"talent_id":"T-09","position":1,"kind":"sample","prompt":"Small work sample","excerpt":"Notebook analysing school-meal waste by weekday; suggested menu swaps that cut waste ~20%.","skills":["analysis"]},{"talent_id":"T-10","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"Thesis model forecasting district-heating demand 24 h ahead; beat the utility''s baseline by 11% MAE and shipped as a nightly job.","skills":["ml","python","analysis"]},{"talent_id":"T-11","position":0,"kind":"scenario","prompt":"Residents complain an apartment block is stuffy every evening. Where do you look?","excerpt":"Check the AHU schedule first — often it steps down at 17:00 for an office pattern. Then filters and exhaust balancing per stairwell.","skills":["hvac","problem"]},{"talent_id":"T-12","position":0,"kind":"voice","prompt":"60-second voice note: a decision you changed with numbers","excerpt":"We moved fast-moving SKUs closer to packing after I pulled pick-path data. Picking time dropped about 15%.","skills":["logistics","analysis"]},{"talent_id":"T-12","position":1,"kind":"scenario","prompt":"Write a query to find late shipments per carrier.","excerpt":"GROUP BY carrier with a HAVING on late ratio; flagged that timestamps are local time so I''d normalise them first.","skills":["sql"]},{"talent_id":"T-13","position":0,"kind":"scenario","prompt":"An elderly client has prescriptions from three doctors. What worries you?","excerpt":"Interactions and duplicates — I''d list every active substance, check for two drugs of the same class, and ask the GP for one medication review.","skills":["medication","patient-care"]},{"talent_id":"T-14","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"Playwright suite with axe-core checks on every PR; cut regression testing from two days to 40 minutes.","skills":["testing","js","a11y"]},{"talent_id":"T-15","position":0,"kind":"scenario","prompt":"A housing company board is sceptical about a heat-pump retrofit. How do you explain it?","excerpt":"Start from their annual heating bill, show payback in years, and bring one reference building they can visit.","skills":["energy","stakeholders"]},{"talent_id":"T-16","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"Redesigned a library booking flow after five guerrilla tests; task time fell from 3 min to 50 s.","skills":["ux"]},{"talent_id":"T-16","position":1,"kind":"voice","prompt":"60-second voice note: what your old job taught you","excerpt":"You read a queue in seconds — who''s in a hurry, who''s confused. That''s half of user research.","skills":["customer","ux"]},{"talent_id":"T-17","position":0,"kind":"scenario","prompt":"A snowstorm closes the main road at 6 am. What''s your first hour?","excerpt":"Re-route the three most time-critical loads, warn customers with honest ETAs, and keep one driver in reserve for whatever breaks next.","skills":["logistics","problem","adapt"]},{"talent_id":"T-18","position":0,"kind":"scenario","prompt":"A battery inverter keeps tripping at noon. Possible causes?","excerpt":"Peak PV output exceeding inverter rating, a loose DC connection heating up, or wrong grid-code setting after an update.","skills":["battery","problem"]},{"talent_id":"T-19","position":0,"kind":"scenario","prompt":"You find an S3 bucket with patient exports set to public. What now?","excerpt":"Lock it immediately, snapshot access logs before they rotate, then tell the DPO — 72-hour GDPR clock may already be running.","skills":["security","cloud"]},{"talent_id":"T-20","position":0,"kind":"voice","prompt":"60-second voice note: a plan you had to change","excerpt":"Exercise supplies for 300 people, and the ferry was cancelled. We split loads across two routes and briefed every team lead the same evening.","skills":["pm","logistics","lead"]},{"talent_id":"T-21","position":0,"kind":"scenario","prompt":"A key supplier announces a 6-week delay. Walk us through your first day.","excerpt":"Quantify stock cover per SKU, rank customers by impact, then call two alternates with a pre-filled RFQ.","skills":["supply","procurement","analysis"]},{"talent_id":"T-22","position":0,"kind":"scenario","prompt":"A resident with dementia becomes agitated during a shower. What do you do?","excerpt":"Stop, lower my voice, give them a towel to hold, and try again later or with a colleague they trust. Note what triggered it.","skills":["elderly-care","patient-care"]},{"talent_id":"T-23","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"Ticket-sales dashboard for a festival: SQL on the box-office DB, one page, three numbers the producer actually asked for.","skills":["analysis","sql","stakeholders"]},{"talent_id":"T-24","position":0,"kind":"scenario","prompt":"Users say the form ''doesn''t work''. How do you investigate?","excerpt":"Reproduce on their device, check the console and network tab, then ask one specific question instead of ''what happened?''.","skills":["js","customer"]},{"talent_id":"T-27","position":0,"kind":"scenario","prompt":"Your CEO wants emissions numbers by Friday. What do you send?","excerpt":"Scope 1–2 from invoices we already have, a clear note on what''s estimated, and a plan for Scope 3 next quarter.","skills":["esg","pm"]},{"talent_id":"T-30","position":0,"kind":"sample","prompt":"Small work sample","excerpt":"Terraform + dbt project that loads open energy-price data hourly with freshness alerts.","skills":["pipelines","cloud","sql"]}]'::jsonb) AS r(talent_id text, position int, kind text, prompt text, excerpt text, skills text[]);

