ion":"Vocational","path":"Linear"},{"talent_id":"T-23","origin":"Finland","education":"Self-taught / bootcamp","path":"Career changer"},{"talent_id":"T-24","origin":"Finland","education":"Self-taught / bootcamp","path":"Career changer"},{"talent_id":"T-27","origin":"EU/EEA","education":"University","path":"Career changer"},{"talent_id":"T-30","origin":"Outside EU","education":"University","path":"Linear"}]'::jsonb) AS r(talent_id text, origin text, education text, path text);

